/* ───────── 🔊 声音网：读音一样或很像（share）· 只差一点（pair） ───────── */
const SN = NET.sound || {zh: {}, en: {}, links: [], by_word: {}};
const SL = {}; (SN.links || []).forEach(l => SL[l.id] = l);
/* 字 / 词 → 读音（中文拼音、英文 IPA），从声音网的例字和线上的词收起来 */
const PRON = {zh: {}, en: {}};
