      if (l.type === "share" && l.by === "syllable" && syl && l.part !== syl) return;
      if (l.type === "share" && l.by === "tone" && syl && toneNumOf(l) !== TONE(syl)) return;
      if (l.type === "pair") { const side = [l.a, l.b].find(x => x.w === c); if (side && syl && side.py && side.py !== syl) return; }
