  keepLine(t, {via, page: "mylang", src: {page: "mylang", phrase: PR.pid}, where: {zh: `🌱 在《你的语言》里练「${p.t}」`, en: `🌱 Practising “${p.t}” in My language`}, borrowed: [{who: p.who, t: p.t}], dr: drs.slice(0, 2)}, SR.querySelector("#sbx .btn"));
